from pathlib import Path
import subprocess, json, hashlib, sys
ROOT=Path('/Users/mohammedshafiqshajahan/.codex/.chatgpt-projects/g-p-6a7341f8cd3c8191b8bc642d3c0a06e6')
REPO=ROOT/'rf2-implementation'; OUT=ROOT/'rf2-source-profile-evidence-v1'
SHA='d608ce8655a024cf7c9e4d78dbeb85b50d20fdc5'
def git(*args): return subprocess.check_output(['git','-C',str(REPO),*args])
def write(p,v):
 p=OUT/p; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(v)
def js(p,v): write(p,json.dumps(v,indent=2,ensure_ascii=False)+'\n')
assert git('rev-parse','HEAD').decode().strip()==SHA
assert not git('status','--porcelain')
files=['backend/app/api/schemas/renal_fluid_entry.py','backend/app/services/renal_fluid_entry_service.py','backend/app/models/clinical/hemodynamics.py','backend/app/models/clinical/common.py','backend/app/demo/icu_chart_entries.py','backend/app/demo/circulatory.py','backend/app/demo/patient_state.py','tests/test_renal_fluid_entry.py','tests/test_rf2_retained_command_compatibility.py']
manifest=[]
for f in files:
 b=git('show',SHA+':'+f); p=OUT/'source'/f;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(b)
 manifest.append({'path':f,'git_blob':git('rev-parse',SHA+':'+f).decode().strip(),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)})
js('source-manifest.json',{'commit':SHA,'tree':git('rev-parse',SHA+'^{tree}').decode().strip(),'files':manifest})
(OUT/'application-commit.raw').write_bytes(git('cat-file','commit',SHA))
sys.path.insert(0,str(REPO/'backend'))
from app.demo.icu_chart_entries import context_facts,NAMESPACE
from app.persistence.canonical import canonical_payload
facts=[f for f in context_facts() if f.kind=='circulatory_event' and f.description.coding and f.description.coding.code in ('input_iv','input_blood','output_urine','output_drain','output_crrt','net_balance_reported','urine_total_reported','balance_total_reported','fluid_challenge','crrt_context')]
examples=[]
for f in facts:
 canonical=canonical_payload(f)
 examples.append({'reference':f.reference.model_dump(mode='json'),'category':f.description.coding.code,'fact':f.model_dump(mode='json'),'canonical_fact':canonical,'digest':hashlib.sha256(canonical.encode()).hexdigest(),'provenance':'Generated by context_facts() from clean baseline source; not retrieved from running database','numerically_eligible':False,'reason':'No approved collection-identity source profile'})
js('examples/producer-examples.json',examples)
# Record every imported application module identity used to generate these examples.
deps=[]
for name,mod in sorted(sys.modules.items()):
 p=getattr(mod,'__file__',None)
 if not p: continue
 p=Path(p)
 try: rel=p.relative_to(REPO).as_posix()
 except ValueError: continue
 if not rel.endswith('.py'):continue
 b=p.read_bytes(); archived=git('show',SHA+':'+rel)
 assert b==archived,rel
 deps.append({'module':name,'path':rel,'sha256':hashlib.sha256(b).hexdigest(),'baseline_equal':True})
js('generation-dependencies.json',deps)
js('profile.json',{'package_version':'1.0','profile_id':'rf2-legacy-chart-profile-assessment/v1','baseline':SHA,'producer_namespace':NAMESPACE,'status':'EVIDENCE_INSUFFICIENT_FOR_NUMERICAL_ELIGIBILITY','profile_approval':False,'implementation_authorized':False,'coverage':'unresolved','source_examples':'baseline-generated synthetic examples, not historical runtime evidence','collection_key':'unsupported','stable_drain_identity':'unsupported','aggregate_membership':'unsupported','new_storage':False,'execution_enabled':False})
cases=[]
def case(id,record,expected,reason,conditional=None):
 cases.append({'id':id,'input':record,'expected_current_disposition':expected,'reason':reason,'conditional_rule_expectation':conditional,'fixture_only':True,'calculator_test_executed':False})
for id in ['fs-IO-output_urine-45','fs-IO-output_drain-15','fs-IO-output_crrt-30','fs-URINE-TOTAL','fs-BALANCE-TOTAL','fs-FLUID-CHALLENGE']:
 e=next(e for e in examples if e['reference']['id']==id)
 case('actual-'+id,{'example_reference':e['reference'],'digest':e['digest']},'exclude','Summary category' if 'TOTAL' in id else 'No approved collection identity; drain identity absent where relevant; fluid challenge may duplicate IV interval intake' if id=='fs-FLUID-CHALLENGE' else 'No approved collection identity; drain identity absent where relevant')
for id,inp,reason,cond in [
 ('eligible-zero',{'amount':'0','unit':'mL'},'Profile gate remains closed','With approved identity and all other checks satisfied, include a genuine zero'),
 ('unknown',{'amount':None,'unit':None},'Missing quantity',None),
 ('absence',{'label':'No drain present'},'No approved durable absence contract; never a volume observation',None),
 ('litres',{'amount':'1.25','unit':'L'},'Profile gate remains closed','With all gates satisfied, exact conversion is 1250 mL'),
 ('independent-drains',{'drain_labels':['A','B'],'same_interval':True},'Names do not establish independent drain identity','With separately approved stable identities and collection keys, both may contribute'),
 ('duplicate-across-category',{'categories':['input_iv','input_blood'],'different_fact_ids':True},'Unresolved shared-collection identity: exclude all affected records',None),
 ('overlap',{'same_source':True,'overlapping_intervals':True},'Unresolved overlap group: exclude all affected records',None),
 ('aggregate-component',{'categories':['output_urine','urine_total_reported']},'Exclude summary; exclude candidate collections too if relationship is unresolved',None),
 ('correction-chain',{'predecessor':'r1','successor':'r2','supersedes':'r1'},'Identity gate still applies','At cutoff containing only r1 select r1; at cutoff containing r2 select only r2'),
 ('withdrawn-terminal',{'r2_status':'withdrawn'},'Exclude; no fallback to r1',None),
 ('competing-revisions',{'successors':['r2a','r2b'],'resolved':False},'Exclude unresolved competing group',None),
 ('interval-end',{'window':['2026-10-08T08:00:00Z','2026-10-08T09:00:00Z'],'interval':['2026-10-08T08:30:00Z','2026-10-08T09:00:00Z']},'Profile gate remains closed','Contained interval qualifies temporally; genuine point at 09:00 does not'),
 ('crossing',{'window':['2026-10-08T08:00:00Z','2026-10-08T09:00:00Z'],'interval':['2026-10-08T07:30:00Z','2026-10-08T08:30:00Z']},'Exclude crossing collection; no proration',None),
 ('near-zero',{'hypothetical_exact_subtotal_mL':'-0.004'},'No calculated runtime result is claimed','Negative, less than 0.01 mL; never Zero'),
 ('retrieval-truncated',{'retrieval_complete':False},'Withhold numeric subtotal',None),
 ('coverage-checkbox',{'user_acknowledged':True},'Cannot override any eligibility failure or establish coverage',None)]:case(id,inp,'exclude' if id!='retrieval-truncated' else 'withhold',reason,cond)
js('fixtures/dispositions.json',cases)
write('GENERATION-LOG.txt',f'Baseline identity and clean working tree checked.\nRead baseline Git objects and generated {len(examples)} synthetic producer examples in memory.\nVerified {len(deps)} imported application Python modules against baseline Git bytes.\nNo database opened, bootstrap invoked, server called, application code edited or application tests run.\nDisposition fixtures are authored expectations, not executed calculator tests.\n')
print(json.dumps({'examples':len(examples),'fixtures':len(cases),'dependencies':len(deps),'output':str(OUT)}))
